// One row per competitor ad, with the dates made readable and the
// long-running creatives flagged. A creative that has been live for months
// is one the competitor keeps paying for, which is the useful signal here.
const weekOf = $now.toFormat('yyyy-MM-dd');
const asDate = (unix) =>
  typeof unix === 'number' && unix > 0
    ? new Date(unix * 1000).toISOString().slice(0, 10)
    : '';

return $input.all().map((item) => {
  const ad = item.json;
  const days = typeof ad.total_days_shown === 'number' ? ad.total_days_shown : '';
  return {
    json: {
      'Week of': weekOf,
      Advertiser: ad.advertiser || '',
      'Ad format': ad.format || '',
      'First shown': asDate(ad.first_shown),
      'Days running': days,
      'Long runner': days !== '' && days >= 90 ? 'YES' : '',
      'Creative link': ad.details_link || '',
      'Creative ID': ad.ad_creative_id || '',
      'Advertiser ID': ad.advertiser_id || '',
    },
  };
});
